--
-- Table structure for table `DraftPick`
--

DROP TABLE IF EXISTS `DraftPick`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `DraftPick` (
  `id` int NOT NULL AUTO_INCREMENT,
  `draftEventId` int NOT NULL,
  `round` int NOT NULL,
  `pickInRound` int NOT NULL,
  `pickNumber` int NOT NULL,
  `draftYear` int NOT NULL,
  `currentTeamId` int NOT NULL,
  `prospectId` int DEFAULT NULL,
  `playerId` int DEFAULT NULL,
  `status` enum('SCHEDULED','ON_CLOCK','PICKED','TRADED','FORFEITED','SKIPPED') NOT NULL DEFAULT 'SCHEDULED',
  `isCompensatory` tinyint(1) NOT NULL DEFAULT '0',
  `acquiredViaTrade` tinyint(1) NOT NULL DEFAULT '0',
  `playerFirstName` varchar(45) DEFAULT NULL,
  `playerLastName` varchar(45) DEFAULT NULL,
  `used` tinyint(1) NOT NULL DEFAULT '0',
  `createdAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `originalTeam` int DEFAULT NULL,
  `position` varchar(45) DEFAULT NULL,
  `college` varchar(255) DEFAULT NULL,
  `selectedAt` datetime DEFAULT NULL,
  `pickGrade` varchar(5) DEFAULT NULL,
  `valueGrade` varchar(5) DEFAULT NULL,
