DROP TABLE IF EXISTS `DraftSimulation`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `DraftSimulation` (
  `id` int NOT NULL AUTO_INCREMENT,
  `draftYear` year NOT NULL,
  `rounds` tinyint NOT NULL,
  `draftSpeed` varchar(10) NOT NULL,
  `rankingSource` varchar(20) NOT NULL,
  `allowTrades` tinyint(1) NOT NULL DEFAULT '0',
  `cpuCpuTrades` tinyint(1) NOT NULL DEFAULT '0',
  `status` varchar(12) NOT NULL,
  `currentOverallPick` smallint NOT NULL DEFAULT '1',
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_DraftSimulation_year` (`draftYear`),
  KEY `idx_DraftSimulation_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
