DROP TABLE IF EXISTS `Job`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Job` (
  `id` int NOT NULL AUTO_INCREMENT,
  `type` varchar(100) NOT NULL,
  `payload` json DEFAULT NULL,
  `status` enum('pending','in_progress','completed','failed','canceled') NOT NULL DEFAULT 'pending',
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `startedAt` datetime(3) DEFAULT NULL,
  `finishedAt` datetime(3) DEFAULT NULL,
  `cancelAt` datetime(3) DEFAULT NULL,
  `cancelReason` varchar(255) DEFAULT NULL,
  `resultCode` varchar(50) DEFAULT NULL,
  `resultJson` json DEFAULT NULL,
  `errorMessage` text,
  `progressPercent` tinyint unsigned NOT NULL DEFAULT '0',
  `totalItems` int unsigned NOT NULL DEFAULT '0',
  `processedItems` int unsigned NOT NULL DEFAULT '0',
  `requestedByPersonId` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `Job_status_idx` (`status`),
  KEY `idx_Job_type` (`type`),
  KEY `idx_Job_type_status` (`type`,`status`),
  KEY `idx_Job_createdAt` (`createdAt`),
  KEY `idx_Job_requestedByPersonId` (`requestedByPersonId`)
) ENGINE=InnoDB AUTO_INCREMENT=136 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

