DROP TABLE IF EXISTS `rosterPlayers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `rosterPlayers` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT (uuid()),
  `teamId` int NOT NULL COMMENT 'References Team.id',
  `playerId` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Reference to external players table if exists',
  `playerName` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `position` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `positionGroup` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `depthChartOrder` int NOT NULL DEFAULT '99' COMMENT 'Order on depth chart, lower = higher',
  `age` int NOT NULL,
  `yearsExperience` int NOT NULL,
  `performanceGrade` decimal(5,2) NOT NULL DEFAULT '50.00' COMMENT '0-100 performance scale',
  `isStarter` tinyint(1) NOT NULL DEFAULT '0',
  `contractYearsRemaining` int NOT NULL DEFAULT '0',
  `injuryStatus` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_rosterPlayers_teamPlayer` (`teamId`,`playerId`),
  KEY `idx_rosterPlayers_teamPosition` (`teamId`,`positionGroup`),
  KEY `idx_rosterPlayers_teamStarter` (`teamId`,`isStarter`),
  KEY `idx_rosterPlayers_depthChart` (`teamId`,`positionGroup`,`depthChartOrder`),
  CONSTRAINT `fk_rosterPlayers_teamId` FOREIGN KEY (`teamId`) REFERENCES `Team` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
